const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=n=>window.icon?.(n)||'', params=['ndwi','turbidity_proxy','chlorophyll_proxy'];
const names={ndwi:'Water index',turbidity_proxy:'Turbidity',chlorophyll_proxy:'Chlorophyll'}, modelNames={det:'DET · Hierarchical Tree-LSTM'};
const palette=['#167a78','#df8c4f','#748ac2','#ac9c69','#7c9d80','#a97895'];
