    $('#download-forecast').disabled=false;$('#download-forecast').onclick=()=>download(csvText(rows.filter(row=>String(row.date).slice(0,10)<=addDays(latestDate(),state.horizon))),`aqualens-${metadata.selected_model||state.model}-${state.horizon}days.csv`,'text/csv');
