function evidenceCard(record,index){return `<article class="evidence-card"><div class="source-meta"><span class="source-number">${String(index+1).padStart(2,'0')}</span><span>${esc(record.source_id||'REFERENCE')}</span>${record.score!==undefined?`<span class="chip">${fmt(record.score,3)} relevance</span>`:''}</div><h3><a href="${esc(safeLink(record.url))}" target="_blank" rel="noopener noreferrer">${esc(record.title)} ${ico('external')}</a></h3><p>${esc(record.text)}</p><p class="fine-print">${esc(record.applicability||'')}</p><div class="source-meta"><span>${record.date?date(record.date):'Publication date not supplied'}</span>${(record.parameters||[]).map(p=>`<span class="chip">${esc(names[p]||p)}</span>`).join('')}</div></article>`;}
