      result=state.mode==='api'?await api(`/api/explain?dataset=${encodeURIComponent(state.dataset)}&zone=${encodeURIComponent(zone)}&parameter=${encodeURIComponent(parameter)}&evidence_id=${encodeURIComponent(state.evidenceId)}${forecast?`&model=${encodeURIComponent(method)}&horizon_days=${state.horizon}&forecast_date=${encodeURIComponent(target)}`:''}`,{timeout:60000}):state.snapshot.explanations?.[key];
