bootstrap();

function modelDiagnostics(){const meta=state.data.evaluation_meta||{},history=meta.history?.det||meta.training_history||[],risk=null;if(!history.length&&!risk)return'';const loss=history.length?`<div class="card-header"><div><h2 class="card-title">Inside the training run</h2><p class="card-subtitle">Saved epoch history · ${esc(modelNames.det)}</p></div><span class="chip">${history.length} epochs</span></div>${chart([{name:'Training objective',color:palette[0],points:history.map(h=>({date:new Date(Date.UTC(2020,0,+h.epoch)).toISOString().slice(0,10),value:h.train_loss}))},{name:history.some(row=>row.validation_score!=null)?'Validation normalized RMSE':'Validation loss',color:palette[1],points:history.map(h=>({date:new Date(Date.UTC(2020,0,+h.epoch)).toISOString().slice(0,10),value:h.validation_score??h.validation_loss}))}],{height:190,xLabel:d=>'Epoch '+(Math.round((Date.parse(d)-Date.UTC(2020,0,1))/86400000)+1)})}<p class="fine-print">The training objective and validation selection score are recorded each epoch and use different scales. Validation dates select the saved checkpoint.</p>`:'';return `<section class="card">${loss}${refinementAuditMarkup(meta)}${risk?`<details class="provenance"><summary>Auxiliary deviation classification · Rule agreement ${ico('chevron')}</summary><div class="stat-grid"><div><span class="muted">Accuracy</span><strong>${fmt(risk.accuracy*100,1)}%</strong></div><div><span class="muted">Macro F1</span><strong>${fmt(risk.macro_f1)}</strong></div><div><span class="muted">Test examples</span><strong>${esc(risk.n)}</strong></div></div>${table(['Actual / predicted','Normal','Warning','Critical'],(risk.confusion_matrix||[]).map((row,i)=>`<tr><td>${['Normal','Warning','Critical'][i]}</td>${row.map(n=>`<td>${esc(n)}</td>`).join('')}</tr>`))}<p class="fine-print">${esc(risk.label_type)}. ${esc(risk.threshold_basis)}. Agreement with generated deviation labels is not environmental risk validation.</p></details>`:''}</section>`;}
function retrievalDiagnostics(){const rows=state.data.retrieval_metrics||[];if(!rows.length)return'';return `<section class="card"><div class="card-header"><div><h2 class="card-title">Retrieval smoke check</h2><p class="card-subtitle">Three hand-authored reference queries · Current library</p></div><span class="chip">Lexical RAG</span></div>${table(['Query','Precision @ 2','Recall @ 2','Retrieved references'],rows.map(r=>`<tr><td>${esc(r.query)}</td><td>${fmt(r.precision_at_2,2)}</td><td>${fmt(r.recall_at_2,2)}</td><td>${esc(r.retrieved)}</td></tr>`))}<p class="fine-print">Small implementation check, not an independent scientific benchmark. Scores do not measure explanation correctness.</p></section>`;}
function forecastSummary(rows){
  const selected=rows.filter(row=>String(row.date).slice(0,10)===state.predictionDate&&row.parameter===state.parameter&&!['all','lake','__lake__'].includes(String(row.zone_id))&&(state.zone==='all'||String(row.zone_id)===state.zone));
  if(!selected.length)return'<div id="forecast-zone-detail"></div>';
  const namesByZone=new Map(allZones().map(zone=>[zone.zone_id,zone.zone_name]));
  return `<details class="provenance" id="forecast-zone-detail"><summary>Zone forecast detail · ${date(state.predictionDate)} ${ico('chevron')}</summary>${table(['Zone','Method','Estimate','Empirical lower','Empirical upper'],selected.map(row=>`<tr><td>${esc(namesByZone.get(String(row.zone_id))||row.zone_id)}</td><td>${esc(row.model_name||forecasterName())}</td><td>${fmt(row.prediction)}</td><td>${fmt(row.lower)}</td><td>${fmt(row.upper)}</td></tr>`))}</details>`;
}





function addDays(value,days){const d=new Date(String(value).slice(0,10)+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+Number(days));return Number.isFinite(d.getTime())?d.toISOString().slice(0,10):'';}
function renderPredictionCards(rows){
  const node=$('#prediction-cards');if(!node)return;
  node.innerHTML=params.map(parameter=>{
    const estimate=(state.forecastSeries?.[parameter]||forecastRows(rows,state.zone,parameter)).find(point=>point.date===state.predictionDate), observed=state.forecastObserved?.[parameter], difference=estimate&&observed?estimate.value-observed.value:null;
    return `<article class="prediction-card forecast-reading" data-indicator="${parameter}"><div class="eyebrow">${esc(indicatorLabel(parameter))}</div><div class="kpi-value">${fmt(estimate?.value)}</div><p class="muted">${date(state.predictionDate)}</p>${difference==null?`<div class="kpi-foot">${estimate?'No previous reading to compare':'No estimate for this date'}</div>`:`<span class="reading-difference">${difference>=0?'+':''}${fmt(difference)} vs. ${date(observed.date,true)}</span>`}${estimate?`<small class="reading-model">${esc(estimate.modelName)}</small>`:''}${estimate?.lower!=null&&estimate?.upper!=null?`<p class="fine-print">Empirical range ${fmt(estimate.lower)} to ${fmt(estimate.upper)}</p>`:''}${estimate?.is_extrapolated?'<span class="badge warning">Extended projection</span>':''}</article>`;
  }).join('');
}
function presentCondition(){const condition=state.data.condition||{},values=params.map(p=>{const supplied=(condition.parameters||[]).find(r=>r.parameter===p),s=series(p,'all',2),v=supplied?.value??s.at(-1)?.value,prev=s.at(-2)?.value,change=supplied?.change_pct??(prev!=null&&prev!==0?(v-prev)/Math.abs(prev)*100:null);return{p,v,change,status:supplied?.status||'Insufficient data'};});return `<section class="condition-banner"><div><div class="eyebrow">PRESENT CONDITION · LATEST AVAILABLE OBSERVATION</div><h2>${date(condition.as_of||latestDate())}</h2><p>${esc(condition.summary||'An observation-based view of the uploaded water measurements and their recent changes.')}</p></div><div><span class="badge neutral">Observed data</span><p class="fine-print">Latest dataset date · No live acquisition</p></div></section><div class="prediction-grid">${values.map(({p,v,change,status})=>`<article class="prediction-card"><div class="eyebrow">${names[p]}</div><div class="kpi-value">${fmt(v)}</div><div class="kpi-foot">${change==null?'No prior reading':`${change>=0?'+':''}${fmt(change,1)}% from prior observation`}</div><p class="fine-print">${p==='ndwi'?'Dimensionless water index':'Supplied satellite proxy · Units unverified'}</p>${badge(`Zone monitoring: ${status}`,({Stable:'normal',Watch:'warning',Unusual:'critical'})[status]||'neutral')}<p class="fine-print">Status reflects the most flagged zone.</p></article>`).join('')}</div>`;}

let weightSource=null,weightCache={};
function weightedPrediction(rows,parameter){if(rows.length===1)return +rows[0].prediction;if(weightSource!==state.data){weightSource=state.data;weightCache={};}let weights=weightCache[parameter];if(!weights){weights={};observations().filter(r=>String(r.date).slice(0,10)===latestDate()&&validRow(r,parameter)).forEach(r=>{weights[r.zone_id]??=new Set();weights[r.zone_id].add(r.cell_id);});weightCache[parameter]=weights;}let total=0,value=0;rows.forEach(r=>{const weight=weights[r.zone_id]?.size||0;total+=weight;value+=+r.prediction*weight;});return total?value/total:rows.reduce((a,b)=>a+ +b.prediction,0)/rows.length;}
function forecastEvidenceMarkup(f){if(!f?.available)return'';return `<div class="notice"><div><strong>${esc(f.model_name||forecasterName(f.model||state.model))} estimate · ${date(f.date)}</strong><p>${fmt(f.prediction)} · ${esc(indicatorLabel(f.parameter))}${f.is_extrapolation||f.is_extrapolated?' · Extended experimental projection':''}</p>${f.prediction_basis?`<p class="fine-print">${esc(f.prediction_basis)}</p>`:''}<p class="fine-print">${esc(f.interval_basis||'Retrieved references help interpret the observations. The numerical estimate comes from the forecast model.')}</p></div></div>`;}
function conditionEvidencePanel(){return `<section class="card"><div class="card-header"><div><h2 class="card-title">What the observations tell us</h2><p class="card-subtitle">Present condition, linked to environmental references</p></div><button class="btn" id="download-explanation">${ico('download')} Export explanation</button></div><div id="explanation-content"><div class="loading">Retrieving evidence for the current condition…</div></div></section>`;}
const dataColumns=['date','zone_id','cell_id','ndwi','turbidity_proxy','chlorophyll_proxy','valid_pixel_fraction','is_observed'];
function dataPreview(rows){return table(dataColumns,rows.slice(-30).reverse().map(row=>`<tr>${dataColumns.map(c=>`<td>${params.includes(c)||c==='valid_pixel_fraction'?fmt(row[c]):esc(String(row[c]??'').slice(0,30))}</td>`).join('')}</tr>`));}
function dataExplorer(rows){return `<div class="filter-row"><label class="search-field">${ico('search')}<input type="search" id="data-row-search" aria-label="Search observations" placeholder="Search date, zone or cell…"></label><span class="muted" id="data-row-count">${rows.length.toLocaleString()} records · Showing latest 30</span></div><div id="data-row-preview">${dataPreview(rows)}</div>`;}

function modelQualityNotice(){const rows=selectedEvaluationRows(),valid=rows.filter(row=>row.r2!=null&&Number.isFinite(+row.r2)),negative=valid.filter(row=>+row.r2<0),limited=valid.some(row=>+row.r2<.2);if(!negative.length&&!limited)return'';return `<div class="notice"><div><strong>${negative.length?'Forecast accuracy needs improvement':'Only limited forecast skill is demonstrated'}</strong><p>${negative.length?`${esc(names[state.parameter])} has negative R² at ${negative.length} evaluated horizon${negative.length===1?'':'s'} for this selected location.`:`Some R² values for ${esc(names[state.parameter])} are close to zero. The forecasts still have substantial errors.`}</p><p class="fine-print">These are retrospective research results, not established operational accuracy. Inspect the selected location’s errors before using the outlook.</p></div></div>`;}



function validationChoices(){
  const choices=['auto','det',...(benchmark().models||[]).map(item=>item.id).filter(id=>id!=='det'&&id!=='auto')];
  return choices.filter(id=>id==='det'||(state.mode==='snapshot'?state.snapshot?.backtests?.[id]?.available:benchmark().saved_history));
}
function validationOptions(){return validationChoices().map(id=>`<option value="${esc(id)}" ${state.validationModel===id?'selected':''}>${id==='auto'?`Auto · ${esc(forecasterName(id))}`:esc(forecasterName(id))}</option>`).join('');}
function historicalName(){return state.validationData?.model_name||state.validationData?.metadata?.selected_model_name||forecasterName(state.validationModel);}
function historicalUsesDet(){return state.validationModel==='det'||state.validationData?.model==='det'||state.validationData?.metadata?.selected_model==='det';}
function validationPage(){return `<div id="validation-content"><section class="card validation-loading"><div class="loading">Loading the independent historical evaluation…</div></section></div>`;}
async function getValidation(){
 const dataset=state.dataset,model=state.validationModel,key=JSON.stringify([dataset,model]);if(state.validationCache[key])return state.validationCache[key];
 let result;
 if(state.mode==='api')result=await api(`/api/backtest?dataset=${encodeURIComponent(dataset)}&model=${encodeURIComponent(model)}`,{timeout:60000});
 else result=state.snapshot?.backtests?.[model]||(model==='det'?state.snapshot?.backtest:null)||{available:false,reason:'No historical validation for this model is included in the saved workspace.'};
 const currentFingerprint=state.data?.evaluation_meta?.fingerprint,savedFingerprint=result?.metadata?.fingerprint;
 if(currentFingerprint&&savedFingerprint&&currentFingerprint!==savedFingerprint)result={available:false,reason:'The saved historical evaluation belongs to different observations. Its predictions cannot be used to validate this dataset.'};
 if(state.dataset===dataset)state.validationCache[key]=result;return result;
}
async function loadValidation(token){
 const dataset=state.dataset;
 try{const result=await getValidation();if(token!==renderToken||state.page!=='validation'||state.dataset!==dataset)return;state.validationData=result;renderValidationResult();}
 catch(error){if(token!==renderToken||state.page!=='validation'||state.dataset!==dataset)return;validationUnavailable(error.message);}
}
function validationUnavailable(reason){const node=$('#validation-content');if(!node)return;node.innerHTML=`<section class="card validation-unavailable"><div class="modal-icon">${ico('chart')}</div><h2>No historical chart is available</h2><p>${esc(reason||'No matching historical forecasts are saved for this dataset and model.')}</p><p class="fine-print">Future forecasts fitted on all observations cannot serve as historical validation.</p><div class="toolbar"><label>Historical model <select class="select" id="validation-model">${validationOptions()}</select></label><button class="btn btn-primary" id="validation-retry">Reload validation</button><button class="btn" id="validation-view-data">View dataset</button></div></section>`;$('#validation-retry').onclick=()=>{delete state.validationCache[JSON.stringify([state.dataset,state.validationModel])];loadValidation(renderToken);};$('#validation-view-data').onclick=()=>navigate('data');$('#validation-model').onchange=event=>{state.validationModel=event.target.value;render();};}
function validationRows(parameter=null,horizon=state.validationHorizon,fullPeriod=false){return(state.validationData?.rows||[]).filter(row=>String(row.zone_id)===state.validationZone&&+row.horizon_days===horizon&&(!parameter||row.parameter===parameter)&&(fullPeriod||(String(row.target_date).slice(0,10)>=state.validationStart&&String(row.target_date).slice(0,10)<=state.validationEnd))&&row.actual!=null&&row.prediction!=null&&Number.isFinite(+row.actual)&&Number.isFinite(+row.prediction)).sort((a,b)=>String(a.target_date).localeCompare(String(b.target_date))||params.indexOf(a.parameter)-params.indexOf(b.parameter));}
function validationScore(rows){const actual=rows.map(row=>+row.actual),errors=rows.map(row=>+row.prediction- +row.actual),n=rows.length;if(!n)return{n:0,mae:null,rmse:null,r2:null,bias:null};const mean=actual.reduce((sum,value)=>sum+value,0)/n,squares=errors.reduce((sum,value)=>sum+value*value,0),denominator=actual.reduce((sum,value)=>sum+(value-mean)**2,0);return{n,mae:errors.reduce((sum,value)=>sum+Math.abs(value),0)/n,rmse:Math.sqrt(squares/n),r2:denominator>0?1-squares/denominator:null,bias:errors.reduce((sum,value)=>sum+value,0)/n};}
function validationGoal(){
 const target=.20,horizons=[8,16,32],scores=params.map(parameter=>horizons.map(horizon=>validationScore(validationRows(parameter,horizon,true))));
 const above=scores.flat().filter(score=>Number.isFinite(score.r2)&&score.r2>target).length, possible=params.length*horizons.length;
 const rows=params.map((parameter,index)=>`<tr><th scope="row">${esc(parameter==='ndwi'?'NDWI':indicatorLabel(parameter))}</th>${horizons.map((horizon,position)=>{
  const score=scores[index][position],available=Number.isFinite(score.r2),passed=available&&score.r2>target,label=available?(passed?'Above goal':'Goal not met'):'No score',value=fmt(score.r2,4);
  return `<td><button class="validation-goal-cell ${passed?'goal-passed':'goal-unmet'}" type="button" data-goal-parameter="${parameter}" data-goal-horizon="${horizon}" aria-label="${esc(indicatorLabel(parameter))}, about ${horizon} days: ${available?`R² ${value}, ${label.toLowerCase()}. `:'No R² score. '}View historical chart" ${score.n?'':'disabled'}><strong>${value}</strong><span>${label}</span></button></td>`;
 }).join('')}</tr>`).join('');
 return `<section class="card validation-goal" aria-labelledby="validation-goal-title"><div class="card-header"><div><div class="eyebrow">HISTORICAL R² GOAL</div><h2 class="card-title" id="validation-goal-title">${above} of ${possible} above 0.20</h2><p class="card-subtitle">${esc(historicalName())} · ${esc(validationZoneLabel())} · Full retrospective period</p></div><span class="badge ${above===possible?'normal':'warning'}">${above===possible?'Goal met':'Goal not met across all nine'}</span></div><table class="validation-goal-table"><thead><tr><th scope="col">Indicator</th>${horizons.map(horizon=>`<th scope="col">≈ ${horizon} days</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table><p class="fine-print">Each cell shows R² for one indicator and forecast horizon. These scores use the full retrospective period and the goal is strictly above 0.20, before rounding. Select a cell to open the matching chart.</p></section>`;
}
function validationZoneLabel(zone=state.validationZone){if(zone==='all')return'Whole lake · origin-weighted zones';return allZones().find(item=>item.zone_id===zone)?.zone_name||zone;}
function validationPeriods(meta){return `<div class="validation-periods"><article class="validation-period train"><span class="eyebrow">TRAINING</span><strong>${date(meta.train_start||report().start)} to ${date(meta.train_end)}</strong><p>Fit model parameters and preprocessing.</p></article><article class="validation-period selection"><span class="eyebrow">VALIDATION</span><strong>${date(meta.validation_start)} to ${date(meta.validation_end)}</strong><p>Choose model settings and compare candidates.</p></article><article class="validation-period test"><span class="eyebrow">RETROSPECTIVE TEST</span><strong>${date(meta.test_start)} to ${date(meta.test_end)}</strong><p>Compare earlier forecasts with later readings.</p></article></div>`;}
function validationChart(parameter,rows){
 if(!rows.length)return'<div class="empty-state">No paired observations in this selection.</div>';
 const model=historicalName(),reference=state.validationOverlay&&!historicalUsesDet()?rows.filter(row=>row.det_prediction!=null&&Number.isFinite(+row.det_prediction)):[];
 const W=860,H=275,P={l:62,r:22,t:22,b:38},dates=[...new Set(rows.map(row=>String(row.target_date).slice(0,10)))].sort(),t0=Date.parse(dates[0]),span=Date.parse(dates.at(-1))-t0||1,values=rows.flatMap(row=>[+row.actual,+row.prediction]).concat(reference.map(row=>+row.det_prediction)),low=Math.min(...values),high=Math.max(...values),pad=(high-low)*.15||Math.max(Math.abs(high)*.1,.02),min=low-pad,max=high+pad,x=value=>P.l+(Date.parse(String(value).slice(0,10))-t0)/span*(W-P.l-P.r),y=value=>P.t+(max-value)/(max-min)*(H-P.t-P.b);
 let grid='';for(let index=0;index<5;index++){const value=max-index*(max-min)/4,position=y(value);grid+=`<line x1="${P.l}" x2="${W-P.r}" y1="${position}" y2="${position}" stroke="#e8eeec"/><text x="${P.l-12}" y="${position+4}" text-anchor="end" fill="#839595" font-size="11">${fmt(value,parameter==='ndwi'?2:1)}</text>`;}
 const ticks=[...new Set([0,.25,.5,.75,1].map(value=>Math.round(value*(dates.length-1))))];grid+=ticks.map(index=>`<text x="${x(dates[index])}" y="${H-12}" text-anchor="middle" fill="#839595" font-size="11">${date(dates[index],true)}</text>`).join('');
 const path=(field,items=rows)=>items.map((row,index)=>`${index&&Date.parse(row.target_date)-Date.parse(items[index-1].target_date)<=18*86400000?'L':'M'}${x(row.target_date).toFixed(2)},${y(+row[field]).toFixed(2)}`).join(' '),selected=rows.find(row=>String(row.target_date).slice(0,10)===state.validationDate);
 const guide=selected?`<line x1="${x(selected.target_date)}" x2="${x(selected.target_date)}" y1="${P.t}" y2="${H-P.b}" stroke="#536c72" stroke-width="1" stroke-dasharray="3 4"/>`:'';
 const markers=rows.map(row=>{const target=String(row.target_date).slice(0,10),chosen=target===state.validationDate;return `<g class="validation-target ${chosen?'is-selected':''}" role="button" tabindex="${chosen?0:-1}" data-validation-date="${esc(target)}" data-validation-parameter="${parameter}" aria-label="Inspect ${esc(names[parameter])}, ${date(target)}: actual ${fmt(row.actual)}, ${esc(model)} ${fmt(row.prediction)}"><title>${esc(names[parameter])} · ${date(target)}
Actual: ${fmt(row.actual)}
 ${esc(model)}: ${fmt(row.prediction)}
 Error (estimate − actual): ${fmt(+row.prediction- +row.actual)}
Forecast made: ${date(row.origin_date)}
Elapsed: ${esc(row.actual_elapsed_days)} days</title><rect class="validation-hit-area" x="${x(target)-6}" y="${P.t}" width="12" height="${H-P.t-P.b}" fill="transparent" pointer-events="all" aria-hidden="true"/><line x1="${x(target)}" x2="${x(target)}" y1="${y(+row.actual)}" y2="${y(+row.prediction)}" stroke="#b8c6cc" opacity="${chosen?'.9':'.35'}"/><circle cx="${x(target)}" cy="${y(+row.actual)}" r="${chosen?5:3.5}" fill="#327fba" stroke="#fff" stroke-width="1.3"/><circle cx="${x(target)}" cy="${y(+row.prediction)}" r="${chosen?5:3.5}" fill="#df8947" stroke="#fff" stroke-width="1.3"/></g>`;}).join('');
 return `<div class="validation-plot"><svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Actual readings versus ${esc(model)} for ${esc(names[parameter])}. Use arrow keys on a selected point.">${grid}${guide}<path d="${path('actual')}" fill="none" stroke="#327fba" stroke-width="2.5" stroke-linejoin="round"/>${reference.length?`<path class="validation-det-overlay" d="${path('det_prediction',reference)}"/>`:''}<path d="${path('prediction')}" fill="none" stroke="#ae6b32" stroke-width="2.5" stroke-dasharray="6 4" stroke-linejoin="round"/>${markers}</svg></div><div class="chart-legend validation-legend"><span><i style="background:#327fba"></i>Actual observed</span><span><i style="background:#ae6b32"></i>${esc(model)} estimate</span>${reference.length?'<span><i style="background:#7053a6"></i>DET reference</span>':''}<span class="muted">Select a point or use the date picker.</span></div>`;
}
function validationParameterCard(parameter){
 const rows=validationRows(parameter),score=validationScore(rows),warning=score.r2!=null&&score.r2<0, title=indicatorLabel(parameter);
 const detRows=historicalUsesDet()?[]:rows.filter(row=>row.det_prediction!=null&&Number.isFinite(+row.det_prediction));
 const reference=detRows.length&&detRows.length===rows.length?validationScore(detRows.map(row=>({...row,prediction:row.det_prediction}))).rmse:null;
 const difference=reference>0?(score.rmse/reference-1)*100:null;
 const comparison=difference==null?'':`<p class="lab-error-comparison"><strong>${Math.abs(difference)<.05?'Similar RMSE to DET':`${fmt(Math.abs(difference),1)}% ${difference<0?'lower':'higher'} RMSE than DET`}</strong><span>The same ${score.n} paired readings were scored for both models.</span></p>`;
 return `<section class="card validation-chart-card ${state.benchmarkParameter===parameter?'parameter-selected':''}"><div class="card-header"><div><div class="eyebrow">${parameter==='ndwi'?'WATER INDEX':'SATELLITE PROXY'}</div><h2 class="card-title" id="validation-chart-${parameter}" tabindex="-1">${esc(title)}</h2><p class="card-subtitle">${esc(validationZoneLabel())} · Approximately ${state.validationHorizon} days ahead</p></div><span class="badge ${warning?'warning':'neutral'}">${warning?'Forecast skill needs improvement':'Retrospective comparison'}</span></div><div class="validation-metrics">${[['MAE ↓',score.mae],['RMSE ↓',score.rmse],['R²',score.r2],['Paired targets',score.n]].map(([label,value],index)=>`<div class="${index===2&&warning?'is-negative':''}"><span>${label}</span><strong>${index===3?score.n:fmt(value,index===2?3:4)}</strong></div>`).join('')}</div>${validationChart(parameter,rows)}${comparison}${warning?'<p class="validation-warning">Negative R²: these predictions had greater squared error than simply using the average of the selected actual values.</p>':''}<p class="fine-print">${parameter==='ndwi'?'NDWI is shown as the supplied dimensionless index.':'Values use the supplied proxy scale; physical concentration units are unverified.'} Scores use the displayed paired targets. Connecting lines show the sequence of readings.</p></section>`;
}
function validationDateDetail(){
 const chosen=validationRows().filter(row=>String(row.target_date).slice(0,10)===state.validationDate), withDet=!historicalUsesDet()&&chosen.some(row=>row.det_prediction!=null), model=historicalName();
 if(!chosen.length)return'<div class="empty-state">No paired forecasts for this target date.</div>';
 return `<div class="validation-inspect-date"><strong>${date(state.validationDate)}</strong><span>${esc(validationZoneLabel())}</span></div>${table(['Parameter','Forecast made','Elapsed days','Actual',`${model} estimate`,...(withDet?['DET reference']:[]),'Error'],chosen.map(row=>`<tr><td><strong>${esc(indicatorLabel(row.parameter))}</strong></td><td>${date(row.origin_date)}</td><td>${esc(row.actual_elapsed_days)}</td><td class="actual-value">${fmt(row.actual)}</td><td class="predicted-value">${fmt(row.prediction)}</td>${withDet?`<td>${fmt(row.det_prediction)}</td>`:''}<td>${fmt(+row.prediction- +row.actual)}</td></tr>`))}<p class="fine-print">Error = estimate minus actual. Recorded observation gaps vary, so the actual elapsed days can differ from the approximate horizon label.</p>`;
}
function comparisonTrainingRecord(meta){return `<section class="card validation-record"><div class="card-header"><div><h2 class="card-title">How the comparison was made</h2><p class="card-subtitle">${esc(historicalName())} · Historical model record</p></div><button class="btn" id="validation-download-audit">${ico('download')} Evaluation audit</button></div><p>${esc(meta.comparison_method||benchmark().method||'Model scoring uses the same paired observations and held-out dates for every candidate.')}</p><p class="fine-print">At every forecast origin, only measurements available by that date can be used. This is a series of shorter forecasts across the test period. Independent confirmation requires new observations.</p></section>`;}
function refinementAuditMarkup(meta){const r=meta?.refinement;if(!r)return'';const previous=r.references?.original_frozen_det,reference=r.references?.last_observed_diagnostic,score=r.validation_score;return `<details class="provenance refinement-audit"><summary>DET refinement and validation audit ${ico('chevron')}</summary><p class="fine-print">The configuration and stopping epoch were chosen before scoring 2022–2023 targets. This period has already been reviewed during development; independent confirmation needs new data.</p>${table(['Pre-2022 validation','Mean normalized RMSE ↓'],[['Archived DET',previous?.score],['Current DET',score],['Last-reading diagnostic only',reference?.score]].filter(row=>row[1]!=null).map(row=>`<tr><td>${esc(row[0])}</td><td>${fmt(row[1],5)}</td></tr>`))}<p class="fine-print">${esc(r.selection_criterion||'Scores balance all three parameters and three native horizons using training-only temporal scales.')} This diagnostic reference is not a second deployed forecasting model.</p><p class="fine-print">Stable coordinate grouping, availability-safe validation, source-aligned anchors for residual candidates, and balanced training objectives were tested. Validation improvements do not establish reliable future forecasts.</p></details>`;}
function validationTrainingRecord(meta){const history=meta.history?.det||meta.training_history||[],config=meta.config||{},loss=history.length?chart([{name:'Training objective',color:'#327fba',points:history.map(row=>({date:new Date(Date.UTC(2020,0,+row.epoch)).toISOString().slice(0,10),value:row.train_loss}))},{name:history.some(row=>row.validation_score!=null)?'Validation normalized RMSE':'Validation loss',color:'#df8947',points:history.map(row=>({date:new Date(Date.UTC(2020,0,+row.epoch)).toISOString().slice(0,10),value:row.validation_score??row.validation_loss??row.val_loss}))}],{height:185,xLabel:value=>'Epoch '+(Math.round((Date.parse(value)-Date.UTC(2020,0,1))/86400000)+1)}):'<p class="muted">No epoch history was included in this evaluation.</p>';return `<section class="card validation-record"><div class="card-header"><div><h2 class="card-title">A separate model for a fair test</h2><p class="card-subtitle">Historical evaluation weights · Frozen after pre-2022 validation</p></div><button class="btn" id="validation-download-audit">${ico('download')} Training audit</button></div><div class="validation-record-grid">${[['Selected epoch',meta.best_epoch],['History window',config.window?`${config.window} observations`:null],['Hidden size',config.hidden],['Learning rate',config.lr],['Seed',meta.seed],['Model family','DET only'],['Weights fitted through',meta.weights_fit_through||meta.train_end],['Model available from',meta.model_available_from||meta.selection_lock_date||meta.selection_available_from||meta.partitions?.validation?.last_observation]].map(([label,value])=>`<div><span>${label}</span><strong>${esc(value??'—')}</strong></div>`).join('')}</div><details class="provenance"><summary>Training and validation learning curves ${ico('chevron')}</summary>${loss}<p class="fine-print">The training objective and validation normalized RMSE use different scales. Only pre-2022 validation selects the checkpoint; 2022–2023 targets do not select settings or stopping epoch.</p></details>${refinementAuditMarkup(meta)}<details class="provenance"><summary>What this experiment establishes ${ico('chevron')}</summary><ul class="validation-method-list"><li>Each prediction is made using observations available by its origin date. The frozen model receives later observations as inputs only after those dates occur. Forecasts are issued only after model selection is complete, so longer horizons have fewer early-2022 target dates.</li><li>This evaluates repeated short-horizon forecasts across the test period. It is not one forecast made in 2021 for the entire following year.</li><li>Whole-lake comparisons apply the same origin-date observation-count weights to actual and predicted zone values. This differs from a raw average across all target-date cells. The whole-lake actual curve can change with the selected horizon because each horizon has a different forecast origin and its own fixed weights.</li><li>Missing or invalid targets are excluded. No uncertainty bands are claimed for this experiment.</li><li>These graphs measure agreement; they do not establish water safety or explain the causes of changes.</li></ul>${(meta.limitations||[]).length?`<p class="fine-print">${esc(meta.limitations.join(' '))}</p>`:''}</details></section>`;}
function renderValidationResult(){
 const data=state.validationData,node=$('#validation-content');if(!node)return;if(!data?.available||!Array.isArray(data.rows)||!data.rows.length){validationUnavailable(data?.reason||data?.message);return;}
 const meta=data.metadata||{},rowZones=[...new Set(data.rows.map(row=>String(row.zone_id)))],zones=Array.isArray(data.available_zones)?data.available_zones.map(zone=>typeof zone==='string'?zone:String(zone.zone_id)):rowZones;
 if(!zones.includes(state.validationZone))state.validationZone=data.default_zone&&zones.includes(data.default_zone)?data.default_zone:zones[0];
 const targetDates=data.rows.map(row=>String(row.target_date).slice(0,10)).sort(),min=targetDates[0],max=targetDates.at(-1);
 if(!state.validationStart||state.validationStart<min||state.validationStart>max)state.validationStart=min;if(!state.validationEnd||state.validationEnd>max||state.validationEnd<min)state.validationEnd=max;
 const rows=validationRows(),dates=[...new Set(rows.map(row=>String(row.target_date).slice(0,10)))].sort();if(!dates.includes(state.validationDate))state.validationDate=dates.at(-1)||'';
 const dateCount=dates.length,weak=params.filter(parameter=>{const score=validationScore(validationRows(parameter));return score.r2!=null&&score.r2<0;});
 const model=historicalName(),hasOverlay=!historicalUsesDet()&&data.rows.some(row=>row.det_prediction!=null),selectionBench=benchmark();
 node.innerHTML=`<section class="validation-hero lab-validation-hero"><div><span class="badge neutral">RETROSPECTIVE TEST</span><h2>Actual readings. Earlier forecasts.</h2><p>Compare ${esc(model)} with recorded measurements. Each prediction uses only readings available at the time. This period was already reviewed during development, so new data is needed to confirm performance.</p></div><div class="validation-hero-seal">${ico('check')}<strong>${esc(model)}</strong><span>Historical forecast</span></div></section>
 ${validationPeriods(meta)}
 <section class="card validation-controls"><div class="card-header lab-validate-title"><div><div class="eyebrow">HISTORICAL WORKSPACE</div><h2 class="card-title">Choose the comparison</h2><p class="card-subtitle">Explore actual recordings and estimates at the same times and locations.</p></div><div class="toolbar"><button class="btn" id="validation-download-selected">${ico('download')} Selected CSV</button><button class="btn" id="validation-download-all">All results CSV</button></div></div>
 <div class="validation-filter-grid lab-filter-grid">
   <label>Historical model<select class="select" id="validation-model">${validationOptions()}</select></label>
   <label>Location<select class="select" id="validation-zone" aria-label="Historical validation zone">${zones.map(zone=>`<option value="${esc(zone)}" ${zone===state.validationZone?'selected':''}>${esc(validationZoneLabel(zone))}</option>`).join('')}</select></label>
   <label>Forecast horizon<select class="select" id="validation-horizon" aria-label="Historical validation horizon">${[[8,1],[16,2],[32,4]].map(([days,steps])=>`<option value="${days}" ${days===state.validationHorizon?'selected':''}>≈ ${days} days · ${steps} reading${steps>1?'s':''} ahead</option>`).join('')}</select></label>
   <label>Target dates from<input class="select" id="validation-start" type="date" min="${esc(min)}" max="${esc(max)}" value="${esc(state.validationStart)}" aria-label="Historical target start date"></label>
   <label>Through<input class="select" id="validation-end" type="date" min="${esc(min)}" max="${esc(max)}" value="${esc(state.validationEnd)}" aria-label="Historical target end date"></label>
   ${selectionBench.available?`<label>Benchmark indicator<select class="select" id="validation-benchmark-indicator">${params.map(parameter=>`<option value="${parameter}" ${parameter===state.benchmarkParameter?'selected':''}>${esc(indicatorLabel(parameter))}</option>`).join('')}</select></label>`:''}
   ${hasOverlay?`<label class="lab-overlay-check"><input id="validation-overlay" type="checkbox" ${state.validationOverlay?'checked':''}>Show DET reference on the charts</label>`:''}
 </div><div class="validation-filter-footer"><span>${dateCount} target dates · ${rows.length} comparisons · ${esc(validationZoneLabel())}</span><button class="text-button" id="validation-reset-range">Full test period</button></div>
 <p class="fine-print">${state.validationZone==='all'?'Whole-lake comparisons use the same observation weights for actual and predicted values. ':''}The elapsed days can differ from the approximate horizon because the source readings are irregular.</p></section>
 ${validationGoal()}
 ${window.AquaForecastUI?.renderBenchmark({benchmark:selectionBench,zone:state.validationZone,zoneLabel:forecastZoneLabel(state.validationZone),parameter:state.benchmarkParameter,parameterLabel:indicatorLabel(state.benchmarkParameter),horizon:state.validationHorizon})||''}
 ${weak.length?`<div class="notice validation-summary-warning">${ico('info')}<p><strong>Limited prediction skill:</strong> ${weak.map(parameter=>esc(names[parameter])).join(', ')} ${weak.length===1?'has':'have'} negative R² in this selection.</p></div>`:''}
 ${!rows.length?'<div class="notice"><p>No paired dates match these filters. Try the full period or a different horizon.</p></div>':''}
 <div class="validation-chart-list">${params.map(validationParameterCard).join('')}</div>
 <section class="card validation-inspector"><div class="card-header"><div><h2 class="card-title">Inspect a forecast</h2><p class="card-subtitle">Select a graph point or choose a recorded target date.</p></div><label class="validation-date-label">Target date<select class="select" id="validation-selected-date" aria-label="Inspect historical forecast date">${dates.map(value=>`<option value="${esc(value)}" ${value===state.validationDate?'selected':''}>${date(value)}</option>`).join('')}</select></label></div><div id="validation-date-detail">${validationDateDetail()}</div></section>
 ${historicalUsesDet()?validationTrainingRecord(meta):comparisonTrainingRecord(meta)}`;
 bindValidationControls();
}
function bindValidationControls(){
 $('#validation-download-selected').disabled=!validationRows().length;$('#validation-selected-date').disabled=!validationRows().length;
 const reselect=id=>{renderValidationResult();document.getElementById(id)?.focus({preventScroll:true});};
 $('#validation-model').onchange=event=>{state.validationModel=event.target.value;const token=++renderToken;loadValidation(token).then(()=>{if(token===renderToken)$('#validation-model')?.focus({preventScroll:true});});};
 $('#validation-zone').onchange=event=>{state.validationZone=event.target.value;reselect('validation-zone');};
 $('#validation-horizon').onchange=event=>{state.validationHorizon=+event.target.value;reselect('validation-horizon');};
 $('#validation-benchmark-indicator')?.addEventListener('change',event=>{state.benchmarkParameter=event.target.value;reselect('validation-benchmark-indicator');});
 $('#validation-overlay')?.addEventListener('change',event=>{state.validationOverlay=event.target.checked;reselect('validation-overlay');});
 const updateRange=event=>{const start=$('#validation-start').value,end=$('#validation-end').value;if(!start||!end||start>end){toast('Choose a start date on or before the end date.',true);return;}state.validationStart=start;state.validationEnd=end;reselect(event.target.id);};
 $('#validation-start').onchange=updateRange;$('#validation-end').onchange=updateRange;
 $('#validation-reset-range').onclick=()=>{state.validationStart='';state.validationEnd='';reselect('validation-reset-range');};
 $('#validation-selected-date').onchange=event=>{state.validationDate=event.target.value;reselect('validation-selected-date');};
 $$('[data-goal-horizon]').forEach(button=>button.onclick=()=>{
  const {goalParameter:parameter,goalHorizon:horizon}=button.dataset;
  state.benchmarkParameter=parameter;state.validationHorizon=+horizon;state.validationStart='';state.validationEnd='';state.validationDate='';
  renderValidationResult();const heading=document.getElementById(`validation-chart-${parameter}`);
  if(heading){heading.focus({preventScroll:true});heading.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 });
 $$('[data-validation-date]').forEach(element=>{
  const {validationDate:target,validationParameter:parameter}=element.dataset;
  const select=(value,focus=false)=>{state.validationDate=value;renderValidationResult();if(focus)$$('[data-validation-date]').find(marker=>marker.dataset.validationDate===value&&marker.dataset.validationParameter===parameter)?.focus({preventScroll:true});};
  element.onclick=()=>select(target);element.onkeydown=event=>{const direction=event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:0;if(direction){const points=validationRows(parameter).map(row=>String(row.target_date).slice(0,10)),next=points[points.indexOf(target)+direction];if(next){event.preventDefault();select(next,true);}}else if(event.key==='Enter'||event.key===' '){event.preventDefault();select(target,true);}};
 });
 const modelFile=state.validationData.model||state.validationModel;
 $('#validation-download-selected').onclick=()=>download(csvText(validationRows()),`aqualens-${modelFile}-historical-${state.validationZone}-${state.validationHorizon}days.csv`,'text/csv');
 $('#validation-download-all').onclick=()=>download(csvText(state.validationData.rows),`aqualens-${modelFile}-historical-all-results.csv`,'text/csv');
 $('#validation-download-audit').onclick=()=>download(JSON.stringify(state.validationData.metadata,null,2),`aqualens-${modelFile}-historical-audit.json`,'application/json');
}
